            color = g[r][c]
            end = c + 1
            while end < w and g[r][end] == color:
                end += 1
            if color != background:
                runs[color] = max(runs.get(color, 0), end - c)
            c = end
    for c in range(w):
        r = 0
        while r < h:
            color = g[r][c]
            end = r + 1
            while end < h and g[end][c] == color:
                end += 1
            if color != background:
                runs[color] = max(runs.get(color, 0), end - r)
            r = end

    marker = max(runs, key=runs.get)
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (background, marker) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
